const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name, cls='') => `<img class="icon ${cls}" src="/static/icons/${name}.svg" alt="">`;
const tabs=[['Media','images'],['Library','squares-four'],['Text','text-t'],['Shapes','shapes'],['Backgrounds','palette'],['Motion','sparkle'],['Templates','squares-four'],['Audio','music-notes'],['Captions','closed-captioning'],['Brand','palette'],['AI','robot']];
const tabLabels={Media:'Materiały',Library:'Biblioteka',Backgrounds:'Tła',Text:'Tekst',Shapes:'Kształty',Motion:'Animacje',Templates:'Szablony',Audio:'Dźwięk',Captions:'Napisy',Brand:'Marka',AI:'Agent AI'};
const kindLabels={image:'obraz',video:'wideo',text:'tekst',caption:'napis',audio:'dźwięk',shape:'kształt'};
const icons={image:'images',video:'film-strip',text:'text-t',caption:'closed-captioning',audio:'waveform',shape:'shapes'};
let state, motions=[], iconLibrary=[], templateLibrary=[], builtinLibrary=[], fontLibrary=[], backgroundLibrary=[], libraryQuery='', libraryKind='all', planTemplateId='product', activeTab='Media', inspectorTab='properties', view='timeline', zoom=1, busy=false, uploading=false, playing=false, drag=false, plan, renderPoll;
let previewRevision=-1, previewProject='', toastTimer, motionPreviewTimer, mobilePanel=null, panelReturnFocus=null;
let libraryCollection='all', selectionTask=Promise.resolve(), selectionVersion=0, pendingSelections=0;
const favoriteAssets=new Set(readPreference('framecore-favorites',[]));
function readPreference(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return Array.isArray(value)?value:fallback;}catch{return fallback;}}
const player=$('#player');
const p=()=>state?.project, selected=()=>p()?.elements.find(e=>state.session.selection.includes(e.id));
const seconds = t => `${String(Math.floor(t/60)).padStart(2,'0')}:${(t%60).toFixed(2).padStart(5,'0')}`;
const assetURL = a => `/assets/${p().id}/${encodeURIComponent(a.file.split('/').pop())}`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function request(path, body, options={}) {
  const res=await fetch(path,{...options,method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Studio-Token':window.STUDIO_TOKEN,...options.headers},body:body===undefined?undefined:JSON.stringify(body)});
  const result=await res.json();if(!res.ok)throw new Error(result.error||`Żądanie nie powiodło się (${res.status})`);return result;
}
async function call(name,args={}) {return request('/api/command',{name,args:{project_id:p().id,expected_revision:p().revision,...args}});}
async function command(name,args={}) {
  if(busy)return;busy=true;$('#saveState').innerHTML='<i></i> Zapisywanie…';
  try {await selectionTask;const result=await call(name,args);if(result.project){state=result;update();}return result;}
  catch(e){toast(e.message);await refresh();throw e;}
  finally{busy=false;$('#saveState').innerHTML='<i></i> Wszystkie zmiany zapisane';}
}
async function refresh(){if(!p())return;state=await request(`/api/project/${p().id}`);update();}
function bind(id, event, handler){$(id).addEventListener(event,e=>{Promise.resolve(handler(e)).catch(err=>toast(err.message));});}
function fillIcons(){for(const [id,name] of Object.entries({undo:'arrow-counter-clockwise',redo:'arrow-clockwise',fitCanvas:'arrows-out-simple',previous:'skip-back',next:'skip-forward',split:'scissors',delete:'trash'}))$('#'+id).innerHTML=icon(name);$('#export').innerHTML=icon('download-simple')+'Eksport';$('#play').innerHTML=icon('play');}
function renderRail(){ $('#rail').innerHTML=tabs.map(([name,i])=>`<button class="rail-button ${activeTab===name?'active':''}" data-tab="${name}" title="${tabLabels[name]}">${icon(i)}<span>${tabLabels[name]}</span></button>`).join(''); }
function setTab(tab){activeTab=tab;renderRail();renderLibrary();$(`[data-tab="${tab}"]`)?.focus({preventScroll:true});if(tab==='AI'){inspectorTab='agent';renderInspector();if(innerWidth<=1050)openPanel('inspector');}else if(innerWidth<=760)openPanel('library');}
function renderLibrary(){
 const box=$('#libraryContent');if(!p())return;
 const heading=(title,sub)=>`<h2 class="panel-heading">${title}</h2><div class="panel-subtitle">${sub}</div>`;
 if(activeTab==='Media'||activeTab==='Audio'){
   const assets=p().assets.filter(a=>activeTab==='Audio'?a.kind==='audio':a.kind!=='audio');
   box.innerHTML=heading(activeTab==='Audio'?'Biblioteka dźwięku':'Twoje materiały',activeTab==='Audio'?'Nadaj historii brzmienie.':'Materiały do Twojego filmu.')+`<button class="import-button" data-import>${icon('upload-simple')}Dodaj ${activeTab==='Audio'?'dźwięk':'materiały'}</button><div class="section-label">MATERIAŁY PROJEKTU <span>${assets.length}</span></div><div class="assets-grid">${assets.map(a=>`<button class="asset-card" data-asset="${a.id}" title="Dodaj ${esc(a.name)} do osi czasu"><div class="asset-thumb">${a.kind==='image'?`<img class="${a.role==='icon'?'library-icon':''}" src="${assetURL(a)}" alt="${esc(a.name)}">`:a.kind==='video'?`<video src="${assetURL(a)}" muted preload="metadata"></video>`:icon('waveform')}${a.duration?`<span class="asset-duration">${seconds(a.duration)}</span>`:''}<span class="asset-add">+</span></div><span class="asset-name">${esc(a.name)}</span><span class="asset-type">${kindLabels[a.kind]}${a.role&&a.role!=='media'?' · '+({product:'produkt',audio:'dźwięk',icon:'ikona',brand:'marka'}[a.role]||esc(a.role)):''}</span></button>`).join('')}</div>${assets.length?'':`<div class="empty-message">Upuść tutaj pliki.<br>Obrazy, wideo i dźwięk pozostają lokalnie.</div>`}<div class="tip-card"><strong>${icon('lightning')} Gotowe do dalszej edycji</strong>Dodaj materiał na oś czasu i dopracuj go. Każdą zmianę możesz cofnąć.</div>`;
 }else if(activeTab==='Text'){
   box.innerHTML=heading('Nadaj słowom formę','Kilka słów w odpowiednim momencie.')+[['Nagłówek','Twój nagłówek',.065,700],['Podtytuł','Detal, który robi różnicę.',.038,500],['Tekst','Opowiedz historię własnymi słowami.',.028,400]].map(([n,text,size,weight])=>`<button class="list-button" data-text="${esc(text)}" data-size="${size}" data-weight="${weight}">${icon('text-t')}<span><strong>${n}</strong><small>Typografia marki · edytowalna</small></span></button>`).join('')+`<div class="section-label">FONTY LOKALNE · POLSKIE ZNAKI</div>${fontLibrary.map(f=>`<button class="font-card" data-font="${esc(f.family)}" style="font-family:'${esc(f.family)}'"><strong>${esc(f.family)}</strong><span>Zażółć gęślą jaźń</span><small>${esc(f.category)} · OFL</small></button>`).join('')}`;
 }else if(activeTab==='Shapes'){
   box.innerHTML=heading('Proste formy','Uporządkuj kompozycję.')+[['Card','Karta'],['Circle','Koło'],['Line','Linia']].map(([n,label])=>`<button class="list-button" data-shape="${n}">${icon('shapes')}<span><strong>${label}</strong><small>Kolor akcentu Twojej marki</small></span></button>`).join('')+`<div class="section-label">IKONY · PHOSPHOR / TABLER / LUCIDE</div><div class="workflow-grid">${iconLibrary.map(i=>`<button class="list-button" data-icon="${i.id}"><img class="icon" src="${esc(i.preview)}" alt=""><span>${esc(i.name)}</span></button>`).join('')}</div>`;
 }else if(activeTab==='Library'){
   box.innerHTML=heading('Materiały wbudowane','Wybrane biblioteki. Dostępne bez internetu.')+`<input id="librarySearch" class="library-search" type="search" aria-label="Szukaj materiałów" placeholder="Szukaj: rakieta, natura, muzyka…" value="${esc(libraryQuery)}"><div class="library-filters">${[['all','Wszystkie'],['icon','Ikony'],['illustration','Ilustracje 3D'],['favorite','Zapisane']].map(([id,name])=>`<button data-library-kind="${id}" class="${libraryKind===id?'active':''}">${name}</button>`).join('')}</div><select id="libraryCollection" class="library-collection" aria-label="Kolekcja materiałów">${['all',...new Set(builtinLibrary.map(a=>a.collection))].map(c=>`<option value="${esc(c)}" ${c===libraryCollection?'selected':''}>${c==='all'?'Wszystkie kolekcje':esc(c)}</option>`).join('')}</select><div id="builtinResults"></div><div class="tip-card">Każdy materiał ma zachowaną licencję i źródło. Ikony mają edytowalny kolor; ilustracje są pełnokolorowe.</div>`;
   renderBuiltinResults();
 }else if(activeTab==='Backgrounds'){
   box.innerHTML=heading('Przestrzeń dla historii','Gradienty, wzory i spokojny ruch.')+`<div class="background-grid">${backgroundLibrary.map(b=>`<button class="background-card ${p().canvas.backgroundPreset===b.id?'active':''}" data-background="${b.id}"><span class="background-swatch" style="background:${esc(b.preview)};background-size:${esc(b.previewSize)}">${b.animated?'◌':''}</span><strong>${esc(b.name)}</strong><small>${{solid:'Jednolite',gradient:'Gradient',grid:'Wzór',dots:'Wzór',lines:'Wzór',grain:'Wzór',animated:'Animowane'}[b.kind]}</small></button>`).join('')}</div>${backgroundLibrary.find(b=>b.id===p().canvas.backgroundPreset)?.animated?`<label class="background-toggle"><input type="checkbox" id="backgroundAnimated" ${p().canvas.backgroundAnimated!==false?'checked':''}> Animuj tło</label>`:''}<div class="tip-card">Tło dopasowuje się do każdego formatu. Ruch jest identyczny w podglądzie i eksporcie.</div>`;
 }else if(activeTab==='Motion'){
   box.innerHTML=heading('Animacje z charakterem','Wybierz kierunek i dopracuj ruch.')+`<div class="section-label">BIBLIOTEKA ANIMACJI <span>${motions.length}</span></div>`+motions.map((m,i)=>`<button class="motion-tile" data-motion="${m.id}"><div class="motion-art" style="${i%3===1?'letter-spacing:3px;font-size:17px':i%3===2?'font-weight:400;font-size:28px':''}"><span class="motion-demo">${['Aa →','FORMA','Cześć.'][i%3]}</span><span class="motion-preview-label">▶ PODGLĄD</span></div><strong>${esc(m.name)}</strong><small>${m.category} · ${{low:'SPOKOJNA',medium:'ŚREDNIA',high:'WYSOKA'}[m.energy]}</small></button>`).join('');
 }else if(activeTab==='Templates'){
   box.innerHTML=heading('Zacznij od historii','Wybierz strukturę swojego filmu.')+workflowCards()+`<button class="primary-button" style="width:100%;margin-top:18px" data-plan>Ułóż plan scen ${icon('arrow-right')}</button><div class="tip-card">Sześć edytowalnych scen, własna typografia i tło. Dodaj swoje materiały albo skorzystaj z ilustracji wbudowanych.</div>`;
 }else if(activeTab==='Captions'){
   box.innerHTML=heading('Napisy w rytmie filmu','Dodaj tekst i ustaw jego czas.')+`<button class="list-button" data-caption>${icon('closed-captioning')}<span><strong>Dodaj napis</strong><small>Przy bieżącym wskaźniku</small></span></button><div class="field"><label>Treść napisu</label><textarea id="captionText" placeholder="Tekst, który chcesz wyświetlić…"></textarea></div><button class="secondary-button" data-caption style="width:100%;margin-top:12px">Dodaj na oś czasu</button><div class="tip-card">Automatyczna transkrypcja wymaga dostawcy. Obecnie napisy edytujesz ręcznie.</div>`;
 }else if(activeTab==='Brand'){
   const b=p().brand;
   box.innerHTML=heading('Twoja marka','Zachowaj spójny wygląd scen.')+`<div class="brand-preview" style="background:${esc(b.colors.background)};color:${esc(b.colors.text)}">${esc(b.name)}</div><div class="field"><label>Nazwa marki</label><input id="brandName" value="${esc(b.name)}"></div><div class="brand-colors">${Object.entries(b.colors).map(([k,v])=>`<label>${{background:'Tło',text:'Tekst',accent:'Akcent'}[k]}<input type="color" data-brand-color="${k}" value="${esc(v)}"></label>`).join('')}</div><div class="field"><label>Krój pisma</label><select id="brandFont">${[...fontLibrary.map(f=>f.family),'Arial','Georgia','Verdana','Times New Roman'].map(f=>`<option ${f===b.font?'selected':''}>${f}</option>`).join('')}</select></div><button class="primary-button" data-save-brand style="width:100%;margin-top:17px">Zastosuj markę</button><div class="section-label">LOGO PROJEKTU</div><button class="list-button" data-use-studio-logo><img class="icon" src="/static/brand/mark-orange.svg" alt=""><span><strong>Dodaj logo FrameCore</strong><small>Znak studia na Twoim filmie</small></span></button><select id="brandLogo" style="width:100%"><option value="">Bez logo</option>${p().assets.filter(a=>a.kind==='image').map(a=>`<option value="${a.id}" ${a.id===b.logoAssetId?'selected':''}>${esc(a.name)}</option>`).join('')}</select><div class="tip-card">Zmiana marki aktualizuje typografię. Całą operację możesz cofnąć.</div>`;
 }else if(activeTab==='AI'){
   box.innerHTML=heading('Twórzmy razem','Agent widzi kontekst Twojego projektu.')+`<div class="agent-intro">${icon('robot')}<h3>Twórczy partner.<br>Z dostępem do edytora.</h3><p>Połącz Codex lub Claude przez MCP. Zaznaczenie, wskaźnik czasu i ostatnie zmiany są wspólne.</p></div><button class="secondary-button" data-connect>${icon('link')}Podłącz agenta</button><div class="section-label">DOSTAWCY MATERIAŁÓW</div><div class="empty-message">Nie skonfigurowano dostawcy.<br>Generowanie obrazu, wideo, głosu i transkrypcja wymagają osobnej integracji i kluczy API.</div><button class="secondary-button" data-provider>Sprawdź możliwości ${icon('arrow-up-right')}</button>`;
 }
}
function field(label,key,value,type='number',step='.1'){return `<label class="field">${label}<input data-property="${key}" type="${type}" value="${esc(typeof value==='number'?Number(value.toFixed(2)):value)}" ${type==='number'?`step="${step}"`:''}></label>`;}
function renderInspector(){
 $('#propertiesTab').classList.toggle('active',inspectorTab==='properties');$('#agentTab').classList.toggle('active',inspectorTab==='agent');
 const box=$('#inspectorContent'),e=selected();if(!p())return;
 if(inspectorTab==='agent'){
   const pending=state.proposals.filter(x=>x.status==='pending'&&x.baseRevision===p().revision);
   box.innerHTML=`<div class="agent-intro">${icon('robot')}<h3>Dopracujmy Twoją historię.</h3><p>Ty i agent edytujecie tę samą oś czasu, ze wspólną historią cofania.</p></div><div class="context-chip">${icon('cursor')}${e?esc(e.text?.slice(0,25)||e.type)+' · zaznaczono':'Zaznacz element'}<span style="margin-left:auto">${seconds(state.session.playhead)}</span></div><textarea id="agentPrompt" class="agent-prompt" placeholder="Przesuń nagłówek o 0,4 sekundy wcześniej i dodaj mocniejsze wejście…"></textarea><button id="proposeEdit" class="primary-button agent-action">${icon('sparkle')}Zaproponuj zmianę</button><div class="inspector-note">Lokalny asystent obsługuje czas i animacje. Swobodne polecenia wymagają zewnętrznego agenta.</div><div class="agent-examples"><button data-suggestion="Przesuń zaznaczony nagłówek o 0,4 sekundy wcześniej i dodaj mocniejsze wejście.">Mocniej i 0,4 s wcześniej ${icon('arrow-up-right')}</button><button data-suggestion="Dodaj wejście premium z rozmyciem do zaznaczonego tekstu.">Dodaj wejście z rozmyciem ${icon('arrow-up-right')}</button></div>${pending.map(x=>`<div class="proposal"><strong>PROPONOWANA ZMIANA</strong>${esc(x.description)}<div>${x.changes.length} zmienionych elementów · ${x.duration}s</div><details><summary>Przejrzyj zmiany</summary><pre>${esc(JSON.stringify(x.commands,null,2))}</pre></details><button data-apply="${x.id}">Zastosuj ${icon('check')}</button><button data-dismiss="${x.id}">Anuluj</button></div>`).join('')}<button class="secondary-button" data-inspect>Sprawdź projekt</button><button class="secondary-button" data-capture>Obejrzyj klatkę</button><div class="section-label">OSTATNIE ZMIANY <span>${state.cursor}</span></div>${state.history.slice(Math.max(0,state.cursor-6),state.cursor).reverse().map(a=>`<div class="activity-entry"><span class="activity-avatar">${a.actor==='agent'?'AI':a.actor==='system'?'F':'T'}</span><div><strong>${esc(a.description)}</strong><small>${a.actor==='agent'?'Agent':a.actor==='system'?'Studio':'Ty'} · historia zmian</small></div></div>`).join('')}<button class="secondary-button" data-connect style="width:100%;justify-content:center">${icon('link')}Podłącz zewnętrznego agenta</button>`;
   return;
 }
 if(!e){box.innerHTML=`<div class="selected-heading">${icon('sliders-horizontal')}Ustawienia projektu</div><div class="selected-meta">Zaznacz klip, aby zmienić jego parametry.</div><div class="inspector-section"><h3>Obszar filmu</h3><div class="field-grid">${field('Szerokość','none',p().canvas.width)}${field('Wysokość','none',p().canvas.height)}</div><div class="inspector-note" style="margin-top:12px">${p().canvas.fps} FPS · ${p().duration}s<br>Format zmienisz nad podglądem.</div></div><div class="inspector-section"><label class="field">Długość projektu · s<input data-project-duration type="number" min="0.1" max="600" step=".1" value="${p().duration}"></label><h3>Jeden wspólny projekt</h3><p class="inspector-note">Właściwości służą do ręcznej edycji. Agent widzi to samo zaznaczenie i oś czasu.</p></div>`;$$('[data-property="none"]').forEach(x=>x.disabled=true);return;}
 const motion=motions.find(m=>m.id===e.motion?.id);
 box.innerHTML=`<div class="selected-heading">${icon(icons[e.type])}<span>${e.type==='text'?'Nagłówek':e.type==='caption'?'Napis':e.type==='shape'?'Kształt':'Klip materiału'}</span><button class="icon-button" data-remove style="margin-left:auto" title="Usuń zaznaczenie">${icon('trash')}</button></div><div class="selected-meta">${esc(p().tracks.find(t=>t.id===e.trackId)?.name||e.type)} · ${e.duration.toFixed(1)} sekund</div>${['text','caption'].includes(e.type)?`<label class="field full">Treść<textarea data-property="text">${esc(e.text)}</textarea></label>`:''}${['text','caption'].includes(e.type)?`<div class="inspector-section"><h3>Typografia</h3><div class="field-grid"><label class="field full">Krój pisma<select data-property="style.fontFamily">${[...fontLibrary.map(f=>f.family),'Arial','Georgia','Verdana','Times New Roman'].map(f=>`<option ${e.style.fontFamily===f?'selected':''}>${f}</option>`).join('')}</select></label>${field('Rozmiar','style.fontSize',e.style.fontSize)}<label class="field">Grubość<select data-property="style.fontWeight">${[400,500,600,700,800,900].map(v=>`<option ${e.style.fontWeight===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field full">Kolor<div class="field-row"><input type="color" data-property="style.color" value="${esc(e.style.color)}"><input type="text" data-property="style.color" value="${esc(e.style.color)}"></div></label><label class="field full">Wyrównanie<select data-property="style.align">${['left','center','right'].map(v=>`<option value="${v}" ${e.style.align===v?'selected':''}>${{left:'Do lewej',center:'Środek',right:'Do prawej'}[v]}</option>`).join('')}</select></label></div></div>`:''}<div class="inspector-section"><h3>Geometria <span style="color:#6e7c65;font-size:8px">PIKSELE</span></h3><div class="alignment-tools" aria-label="Wyrównanie w kadrze">${[['left','Do lewej','⊢'],['center','Wyśrodkuj poziomo','↔'],['right','Do prawej','⊣'],['top','Do góry','⤒'],['middle','Wyśrodkuj pionowo','↕'],['bottom','Do dołu','⤓']].map(([id,name,glyph])=>`<button ${e.type==='audio'?'disabled':''} data-align="${id}" aria-label="${name}" title="${name}">${glyph}</button>`).join('')}</div><div class="field-grid">${field('X','x',e.x)}${field('Y','y',e.y)}${field('Szerokość','width',e.width)}${field('Wysokość','height',e.height)}${field('Obrót','rotation',e.rotation)}${field('Skala','scale',e.scale)}</div></div><div class="inspector-section"><h3>Czas</h3><div class="field-grid">${field('Początek · s','start',e.start)}${field('Długość · s','duration',e.duration)}${e.assetId?field('Początek źródła · s','sourceStart',e.sourceStart):''}${field('Widoczność','opacity',e.opacity)}</div></div><div class="inspector-section"><h3>Animacja <button class="quiet-button" data-motion-tab>Przeglądaj</button></h3><div class="motion-pill">${icon('sparkle')}<span>${esc(motion?.name||'Bez animacji')}<small>${e.motion?.duration||0}s · ${{low:'spokojna',medium:'średnia',high:'wysoka'}[motion?.energy]||'bez ruchu'} · energia</small></span>${icon('caret-down')}</div>${e.motion?`<div style="margin-top:12px">${field('Czas wejścia · s','motion-duration',e.motion.duration)}</div>`:''}</div>${e.type==='audio'?audioControls(e):''}<div class="inspector-section"><button class="secondary-button" data-duplicate>Duplikuj klip</button>${e.type!=='audio'?`<button class="secondary-button" data-keyframes>Klatki kluczowe · ${e.keyframes.length}</button>`:''}</div><div class="inspector-note">Zmiany są wspólne z agentem. Każdą operację możesz cofnąć.</div>`;
}
function renderTimeline(){
 const box=$('#timelineContent');if(!p())return;
 $('#timelineTab').classList.toggle('active',view==='timeline');$('#storyboardTab').classList.toggle('active',view==='storyboard');
 $('#clipCount').textContent=p().elements.length+' klipów';
 if(view==='storyboard'){box.innerHTML=`<div class="storyboard-grid">${p().scenes.map(s=>`<button class="story-card ${state.session.playhead>=s.start&&state.session.playhead<s.start+s.duration?'active':''}" data-scene-time="${s.start}"><small>${esc(s.name)}</small><strong>${esc(s.message)}</strong><span>${s.duration.toFixed(1)}s · ${esc({headline_impact:'mocne wejście',title_reveal:'odsłonięcie tytułu'}[s.motionIntent]||s.motionIntent)}</span></button>`).join('')||'<div class="empty-message">Przygotuj plan przed montażem. <button class="secondary-button" data-plan>Ułóż plan</button></div>'}</div>`;return;}
 const ticks=[];const count=Math.min(30,Math.ceil(p().duration));for(let i=0;i<=count;i++){const t=i*p().duration/count;ticks.push(`<span class="ruler-tick" style="left:${t/p().duration*100}%">${Math.round(t)}s</span>`);}
 box.innerHTML=`<div class="timeline-sheet" style="width:calc(114px + (100% - 114px) * ${zoom})"><div class="time-ruler" data-ruler>${ticks.join('')}</div>${p().tracks.map(t=>`<div class="timeline-track"><div class="track-label ${t.locked?'locked':''}">${icon(icons[t.kind]||'shapes')}<span>${esc(t.name)}</span><button data-track="${t.id}" data-track-prop="${t.kind==='audio'?'muted':'hidden'}" title="${t.kind==='audio'?'Wycisz ścieżkę':'Ukryj ścieżkę'}">${icon(t.kind==='audio'?'speaker-high':'eye')}</button></div><div class="track-lane" data-lane="${t.id}">${p().elements.filter(e=>e.trackId===t.id).map(e=>`<button class="clip ${e.type} ${state.session.selection.includes(e.id)?'selected':''}" data-clip="${e.id}" style="left:${e.start/p().duration*100}%;width:${e.duration/p().duration*100}%;opacity:${t.hidden||t.muted?.45:1}" title="${esc(e.text||e.type)} · ${e.start.toFixed(2)}s"><i class="trim-handle"></i>${icon(icons[e.type])}<span>${esc(e.assetId?p().assets.find(a=>a.id===e.assetId)?.name:e.text||'Kształt')}</span><i class="trim-handle right"></i></button>`).join('')}</div></div>`).join('')}<div class="playhead"><span class="playhead-label"></span></div></div>`;
 paintPlayhead();
}
function paintPlayhead(){const sheet=$('.timeline-sheet'),line=$('.playhead');if(sheet&&line){const laneWidth=sheet.clientWidth-114;line.style.left=114+state.session.playhead/p().duration*laneWidth+'px';}}
function fitCanvas(){if(!p())return;const area=$('.canvas-area'),r=p().canvas.width/p().canvas.height;const maxH=area.clientHeight-40,maxW=area.clientWidth-45;const h=Math.min(maxH,maxW/r);$('#canvasWrap').style.height=h+'px';$('#canvasWrap').style.width=h*r+'px';$('#canvasWrap').style.aspectRatio=r;renderOverlay();}
function renderOverlay(){
 if(!p())return;const t=state.session.playhead,overlay=$('#canvasOverlay'),scale=$('#canvasWrap').clientWidth/p().canvas.width;
 overlay.innerHTML=p().tracks.flatMap(track=>p().elements.filter(e=>e.trackId===track.id&&!track.hidden&&e.type!=='audio'&&e.start<=t&&t<e.start+e.duration).map(e=>`<button aria-label="Zaznacz ${esc(e.type+' '+(e.text?.slice(0,35)||''))}" class="canvas-hit ${state.session.selection.includes(e.id)?'selected':''}" data-canvas="${e.id}" style="left:${e.x*scale}px;top:${e.y*scale}px;width:${e.width*scale}px;height:${e.height*scale}px;transform:rotate(${e.rotation}deg) scale(${e.scale})"><span>${esc(e.type==='text'?'Nagłówek':kindLabels[e.type])}</span></button>`)).join('');
}
function update(){
 if(!p())return;$('#projectMenu').textContent=p().metadata.name+' ⌄';$('#projectMenu').title='Projekty · '+p().metadata.name;$('.project-kind').textContent=p().canvas.width<p().canvas.height?'Rolka':'Film';$('#canvasSize').textContent=p().canvas.width+' × '+p().canvas.height;
 const formats={'1080x1920':'9:16','1080x1350':'4:5','1080x1080':'1:1','1920x1080':'16:9'};$('#formatButton').textContent=(formats[`${p().canvas.width}x${p().canvas.height}`]||'Własny')+' ⌄';
 $('#timeEnd').textContent=seconds(p().duration);$('#timeNow').textContent=seconds(state.session.playhead);$('#revision').textContent='Rewizja '+p().revision;
 $('#undo').disabled=!state.canUndo;$('#redo').disabled=!state.canRedo;
 const scene=p().scenes.find(s=>s.start<=state.session.playhead&&state.session.playhead<s.start+s.duration);$('#sceneName').textContent=scene?`${String(p().scenes.indexOf(scene)+1).padStart(2,'0')} ${scene.name}`:'Kompozycja';
 const libraryScroll=$('#libraryContent').scrollTop,inspectorScroll=$('#inspectorContent').scrollTop;
 renderLibrary();renderInspector();renderTimeline();fitCanvas();$('#libraryContent').scrollTop=libraryScroll;$('#inspectorContent').scrollTop=inspectorScroll;
 if(previewRevision!==p().revision||previewProject!==p().id){previewRevision=p().revision;previewProject=p().id;stopPlayback();player.setAttribute('width',p().canvas.width);player.setAttribute('height',p().canvas.height);player.setAttribute('src',`/composition/${p().id}?revision=${p().revision}`);}
 $('#split').disabled=!selected();$('#delete').disabled=!selected();
}
async function choose(eid){
 if(busy)return;const projectId=p().id,version=++selectionVersion,ids=eid?[eid]:[];
 state.session.selection=ids;renderInspector();renderTimeline();renderOverlay();pendingSelections++;
 selectionTask=selectionTask.catch(()=>{}).then(async()=>{
   const result=await request('/api/command',{name:'set_selection',args:{project_id:projectId,element_ids:ids}});
   if(p().id===projectId&&version===selectionVersion){state=result;renderInspector();renderTimeline();renderOverlay();}
 }).finally(()=>pendingSelections--);
 await selectionTask;
}
async function seek(t,persist=true){stopPlayback();t=Math.min(p().duration,Math.max(0,t));state.session.playhead=t;player.seek(t);$('#timeNow').textContent=seconds(t);paintPlayhead();renderOverlay();const scene=p().scenes.find(s=>s.start<=t&&t<s.start+s.duration);$('#sceneName').textContent=scene?`${String(p().scenes.indexOf(scene)+1).padStart(2,'0')} ${scene.name}`:'Kompozycja';if(persist)await call('set_playhead',{time:t});}
function stopPlayback(){clearTimeout(motionPreviewTimer);playing=false;player.pause();$('#play').innerHTML=icon('play');$('#play').setAttribute('aria-label','Odtwarzaj');}
function togglePlay(){if(playing){stopPlayback();call('set_playhead',{time:state.session.playhead}).catch(e=>toast(e.message));}else{playing=true;player.play();$('#play').innerHTML=icon('pause');$('#play').setAttribute('aria-label','Pauza');}}
function openModal(html){closePanel();$('#modalContent').innerHTML=html;$('#modal').showModal();}
function closeModal(){clearInterval(renderPoll);$('#modal').close();}
function modalHeader(eyebrow,title,subtitle){return `<div class="modal-header"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div><button class="icon-button" data-close aria-label="Zamknij">${icon('x')}</button></div>`;}
function workflowCards(limit=12){return `<div class="workflow-grid">${templateLibrary.slice(0,limit).map((t,i)=>`<button class="workflow-card ${i===0?'active':''}" data-workflow="${esc(t.name)}" data-template="${t.id}"><div class="workflow-art" style="background:${esc(t.look.background)};color:${esc(t.look.text)};font-family:'${esc(t.look.font)}'"><small>${esc(t.look.font.toUpperCase())}</small>${esc(t.name)}</div><span>${esc(t.name)} ${icon('arrow-up-right')}</span></button>`).join('')}</div>`;}
function renderBuiltinResults(){
 const query=libraryQuery.toLocaleLowerCase('pl');
 const items=builtinLibrary.filter(a=>(libraryKind==='all'||a.kind===libraryKind||(libraryKind==='favorite'&&favoriteAssets.has(a.id)))&&(libraryCollection==='all'||a.collection===libraryCollection)&&[a.name,a.collection,...a.tags].join(' ').toLocaleLowerCase('pl').includes(query));
 $('#builtinResults').innerHTML=`<div class="section-label">MATERIAŁY <span>${items.length}</span></div><div class="assets-grid">${items.map(a=>`<div class="asset-tile"><button class="asset-card" data-builtin="${a.id}" title="${esc(a.name)} · ${esc(a.collection)} · ${esc(a.license)}"><div class="asset-thumb"><img class="${a.kind==='icon'?'library-icon':'builtin-illustration'}" src="${esc(a.preview)}" alt="${esc(a.name)}" loading="lazy"><span class="asset-add">+</span></div><span class="asset-name">${esc(a.name)}</span><span class="asset-type">${esc(a.collection)} · ${esc(a.license)}</span></button><button class="favorite-button" data-favorite="${a.id}" aria-pressed="${favoriteAssets.has(a.id)}" aria-label="${favoriteAssets.has(a.id)?'Usuń z zapisanych':'Zapisz materiał'}: ${esc(a.name)}" title="${favoriteAssets.has(a.id)?'Usuń z zapisanych':'Zapisz materiał'}">${favoriteAssets.has(a.id)?'★':'☆'}</button></div>`).join('')}</div>${items.length?'':`<p class="empty-message">${libraryKind==='favorite'?'Zapisz ulubione materiały gwiazdką.':'Brak pasujących materiałów. Zmień wyszukiwanie lub kolekcję.'}</p>`}`;
}

function openPanel(name){
 if(mobilePanel===name)return;
 if(mobilePanel)closePanel();
 mobilePanel=name;panelReturnFocus=document.activeElement;
 const panel=$('.'+name);panel.dataset.panelOpen='';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');
 if(name==='library')panel.setAttribute('aria-label',tabLabels[activeTab]||'Biblioteka');
 $('#panelBackdrop').hidden=false;
 for(const node of $$('.topbar,.creation-rail,.workspace,.timeline,.library,.inspector,.statusbar'))if(node!==panel)node.inert=true;
 panel.querySelector('[data-close-panel]').focus({preventScroll:true});
}
function closePanel(){
 if(!mobilePanel)return;
 const panel=$('.'+mobilePanel);delete panel.dataset.panelOpen;panel.removeAttribute('role');panel.removeAttribute('aria-modal');
 for(const node of $$('.topbar,.creation-rail,.workspace,.timeline,.library,.inspector,.statusbar'))node.inert=false;
 $('#panelBackdrop').hidden=true;mobilePanel=null;
 if(panelReturnFocus?.isConnected)panelReturnFocus.focus({preventScroll:true});
}
function panelKeydown(event){
 if(!mobilePanel)return false;
 if(event.key==='Escape'){event.preventDefault();closePanel();return true;}
 if(event.key==='Tab'){
  const nodes=[...$('.'+mobilePanel).querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.getClientRects().length);
  const first=nodes[0],last=nodes.at(-1);
  if(event.shiftKey&&(document.activeElement===first||!nodes.includes(document.activeElement))){event.preventDefault();last?.focus();}
  else if(!event.shiftKey&&(document.activeElement===last||!nodes.includes(document.activeElement))){event.preventDefault();first?.focus();}
 }
 return true;
}
async function previewSelectedMotion(){
 const e=selected();if(!e)return;
 if(!player.ready)await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{player.removeEventListener('ready',done);reject(new Error('Podgląd nie jest jeszcze gotowy.'));},8000);const done=()=>{clearTimeout(timer);resolve();};player.addEventListener('ready',done,{once:true});});
 await seek(e.start);togglePlay();
 motionPreviewTimer=setTimeout(()=>{stopPlayback();call('set_playhead',{time:state.session.playhead}).catch(err=>toast(err.message));},Math.min(e.duration,(e.motion?.duration||.8)+1.1)*1000);
}
async function alignSelected(alignment){
 const e=selected();if(!e||e.type==='audio')return;
 const w=p().canvas.width,h=p().canvas.height;
 const x={left:0,center:(w-e.width)/2,right:w-e.width}[alignment];
 const y={top:0,middle:(h-e.height)/2,bottom:h-e.height}[alignment];
 await command('move_element',{element_id:e.id,x:x===undefined?e.x:x,y:y===undefined?e.y:y});
}

