function keyframeModal(){const e=selected();openModal(modalHeader('RUCH W CZASIE','Klatki kluczowe','Ustaw wartość na początku i końcu klipu. Przejście jest liniowe.')+`<div class="modal-body"><label class="field">Właściwość<select id="keyframeProperty">${[['x','Pozycja X'],['y','Pozycja Y'],['scale','Skala'],['rotation','Obrót'],['opacity','Widoczność']].map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><div class="creation-fields"><label class="field">Początek · 0 s<input id="keyframeFrom" type="number" step=".1" value="${e.x}"></label><label class="field">Koniec · ${e.duration} s<input id="keyframeTo" type="number" step=".1" value="${e.x}"></label></div><p class="inspector-note">Zapis zastępuje klatki wybranej właściwości, zachowując pozostałe.</p><div class="modal-actions"><button class="secondary-button" id="clearKeyframes">Usuń wszystkie klatki</button><button class="primary-button" id="saveKeyframes">Zapisz ruch</button></div></div>`);$('#keyframeProperty').addEventListener('change',ev=>{const value=e[ev.target.value];$('#keyframeFrom').value=value;$('#keyframeTo').value=value;});}
function newProjectModal(){openModal(modalHeader('POCZĄTEK NOWEJ HISTORII','Jaki film chcesz stworzyć?','Wybierz kierunek, dodaj materiały i ułóż historię.')+`<div class="modal-body">${workflowCards(4)}<textarea class="prompt-box" id="briefPrompt" placeholder="Opisz pomysł na film…">Stwórz elegancką rolkę 15 sekund o moim produkcie.</textarea><div class="creation-fields"><label class="field">Nazwa projektu<input id="newName" value="Historia mojego produktu"></label><label class="field">Format<select id="newFormat"><option>9:16</option><option>4:5</option><option>1:1</option><option>16:9</option></select></label><label class="field">Długość · s<input id="newDuration" type="number" min="3" max="600" value="15"></label></div><div class="modal-actions"><small>Utwórz projekt, następnie dodaj zdjęcie produktu, logo i nagrania.</small><button id="createProject" class="primary-button">Utwórz projekt ${icon('arrow-right')}</button></div></div>`);}
async function planModal(templateId='product'){
 const result=await call('plan_storyboard',{title:p().metadata.name,template_id:templateId});plan=result.scenes;planTemplateId=result.template_id;
 openModal(modalHeader('NAJPIERW HISTORIA','Jeden kierunek. Sześć scen.','Sprawdź teksty przed zbudowaniem edytowalnego montażu.')+`<div class="modal-body"><div class="plan-list">${plan.map((s,i)=>`<div class="plan-item"><small>${String(i+1).padStart(2,'0')} / ${esc(s.name)}</small><textarea data-plan-message="${i}">${esc(s.message)}</textarea><span>${s.duration.toFixed(1)}s · ${esc({headline_impact:'mocne wejście',title_reveal:'odsłonięcie tytułu'}[s.motionIntent]||s.motionIntent)}</span></div>`).join('')}</div><div class="modal-actions"><small>Plan startowy z szablonu. ${p().assets.length} materiałów w projekcie. Napisy są edytowalnymi etykietami scen; transkrypcja wymaga integracji.${p().elements.length?' Ta operacja zastąpi obecny montaż. Najpierw przejrzyj propozycję.':''}</small><button id="assemble" class="primary-button">${icon('sparkle')}Zbuduj montaż</button></div></div>`);
}
function formatModal(){openModal(modalHeader('DOPASUJ FORMAT','Twój film na każdym ekranie.','Geometria skaluje się do nowego formatu. Zmianę możesz cofnąć.')+`<div class="modal-body"><div class="format-grid">${[['9:16','Reels / Shorts',1080,1920],['4:5','Post w mediach społecznościowych',1080,1350],['1:1','Kwadrat',1080,1080],['16:9','Poziomy',1920,1080]].map(([f,n,w,h])=>`<button class="format-option" data-format="${f}"><span class="format-box" style="aspect-ratio:${w}/${h}"></span><strong>${f}</strong><small>${n} · ${w} × ${h}</small></button>`).join('')}</div></div>`);}
async function exportModal(){
 openModal(modalHeader('OD MONTAŻU DO FILMU','Eksportuj film','Ten sam projekt, renderowany lokalnie.')+`<div class="modal-body"><div class="creation-fields"><label class="field">Rozdzielczość<input value="${p().canvas.width} × ${p().canvas.height}" disabled></label><label class="field">Klatki na sekundę<input value="${p().canvas.fps} FPS" disabled></label><label class="field">Format<input value="MP4 / H.264" disabled></label></div><div class="inspector-note">${p().duration} sekund · rewizja ${p().revision} · ${p().elements.filter(e=>e.type==='audio').length?'z dźwiękiem z osi czasu':'bez ścieżki dźwiękowej'}</div><div id="exportStatus"></div><div class="modal-actions"><small>Eksport zapisuje bieżącą rewizję. Możesz dalej edytować; dłuższy film wymaga więcej czasu.</small><button id="startExport" class="primary-button">${icon('download-simple')}Renderuj MP4</button></div></div>`);
}
function connectModal(){openModal(modalHeader('AGENT W TWOIM STUDIO','Połącz przez MCP','Edytuj zaznaczony element. Każdą zmianę możesz cofnąć.')+`<div class="modal-body"><p class="panel-subtitle">Dodaj FrameCore do klienta Codex, Claude lub innego klienta MCP. Wpisz pełne ścieżki do repozytorium i Pythona.</p><pre class="connect-code">${esc(JSON.stringify({mcpServers:{framecore:{command:'/absolute/path/to/vstudio/.venv/bin/python',args:['/absolute/path/to/vstudio/framecore.py','mcp'],cwd:'/absolute/path/to/vstudio'}}},null,2))}</pre><div class="tip-card">Spróbuj: „Przesuń zaznaczony nagłówek o 0,4 sekundy wcześniej i dodaj mocniejsze wejście.” Agent odczytuje get_selection, proponuje zmiany i stosuje je do aktualnej rewizji.</div><div class="modal-actions"><small>Edycja projektu przez MCP nie wymaga klucza API.</small><button data-close class="primary-button">Rozumiem ${icon('check')}</button></div></div>`);}
async function upload(files){
 if(uploading||!files.length)return;uploading=true;
 try{for(const file of files){$('#saveState').innerHTML='<i></i> Dodawanie '+esc(file.name)+'…';let role='media';if(file.type.startsWith('image/'))role=/logo/i.test(file.name)?'logo':'product';const res=await fetch(`/api/upload/${p().id}?name=${encodeURIComponent(file.name)}&role=${role}&revision=${p().revision}`,{method:'POST',headers:{'X-Studio-Token':window.STUDIO_TOKEN,'Content-Type':file.type||'application/octet-stream'},body:file});const data=await res.json();if(!res.ok)throw new Error(data.error);state=data;update();}toast(`Dodano materiałów: ${files.length}`);}finally{uploading=false;$('#saveState').innerHTML='<i></i> Wszystkie zmiany zapisane';$('#fileInput').value='';}
}
async function useStudioLogo(){
 if(busy||uploading)return;
 const response=await fetch('/static/brand/framecore-mark.png');if(!response.ok)throw new Error('Nie udało się wczytać logo studia.');
 await upload([new File([await response.blob()],'FrameCore-logo.png',{type:'image/png'})]);
 const asset=p().assets.at(-1),w=p().canvas.width,h=p().canvas.height;
 const stateAfter=await command('propose_changes',{description:'Dodaj znak FrameCore do filmu',commands:[
  {name:'set_brand',args:{brand:{logoAssetId:asset.id},restyle:false}},
  {name:'add_image',args:{assetId:asset.id,start:0,duration:p().duration,x:w*.84,y:h*.04,width:w*.1,height:w*.1,motion:{id:'logo-settle',duration:.6}}}
 ]});
 const proposal=stateAfter?.proposals.at(-1);if(!proposal)return;
 const applied=await command('apply_proposal',{proposal_id:proposal.id});if(applied)await choose(applied.project.elements.at(-1).id);
 toast('Logo studia dodane do filmu. Montaż znaku cofniesz jednym krokiem.');
}
async function addAsset(aid){const a=p().assets.find(a=>a.id===aid),remain=p().duration-state.session.playhead;if(remain<.1)return toast('Przesuń wskaźnik przed koniec projektu.');const s=await command('add_'+a.kind,{assetId:aid,start:state.session.playhead,duration:Math.min(a.duration||3,remain),...(a.kind==='video'?{x:0,y:0,width:p().canvas.width,height:p().canvas.height}:{})});if(s)await choose(s.project.elements.at(-1).id);}
async function proposeEdit(){
 const e=selected();if(!e)return toast('Najpierw zaznacz jeden element.');const prompt=$('#agentPrompt').value.trim();if(!prompt)return toast('Opisz zmianę czasu lub animacji.');
 const commands=[];const earlier=/earlier|wcześniej|wczesniej/i.test(prompt),later=/later|później|pozniej/i.test(prompt);const match=prompt.match(/(\d+(?:[.,]\d+)?)\s*(?:s(?:econds?)?|sekund)/i);
 if(earlier||later){if(!match)return toast('Podaj czas, na przykład „0,4 sekundy wcześniej”.');const delta=Number(match[1].replace(',','.'));commands.push({name:'move_clip',args:{element_id:e.id,start:Math.max(0,e.start+(earlier?-delta:delta))}});}
 if(/harder|impact|mocniej|mocniejsze/i.test(prompt))commands.push({name:'apply_motion',args:{element_id:e.id,motion_id:'impact-rise',duration:.5}});
 else if(/premium|blur/i.test(prompt))commands.push({name:'apply_motion',args:{element_id:e.id,motion_id:'premium-blur-reveal',duration:.8}});
 else if(/fade|pojawienie/i.test(prompt))commands.push({name:'apply_motion',args:{element_id:e.id,motion_id:'soft-fade',duration:.6}});
 if(!commands.length)return toast('Podaj zmianę czasu, rozmycie lub mocne wejście. Inne zmiany zleć agentowi MCP.');
 await command('propose_changes',{description:prompt,commands});toast('Propozycja gotowa do przejrzenia.');
}
function setupEvents(){
 bind('#openInspector','click',()=>openPanel('inspector'));
 bind('#panelBackdrop','click',closePanel);
 for(const button of $$('[data-close-panel]'))button.addEventListener('click',closePanel);
 window.addEventListener('resize',()=>{if(mobilePanel&&(innerWidth>1050||(mobilePanel==='library'&&innerWidth>760)))closePanel();});
 bind('#rail','click',e=>{const b=e.target.closest('[data-tab]');if(b)setTab(b.dataset.tab);});
 bind('#propertiesTab','click',()=>{inspectorTab='properties';renderInspector();});bind('#agentTab','click',()=>{inspectorTab='agent';renderInspector();});
 bind('#newProject','click',newProjectModal);bind('#undo','click',()=>command('undo'));bind('#redo','click',()=>command('redo'));bind('#export','click',exportModal);
 bind('#formatButton','click',formatModal);bind('#fitCanvas','click',fitCanvas);bind('#play','click',togglePlay);bind('#previous','click',()=>seek(state.session.playhead-1/p().canvas.fps));bind('#next','click',()=>seek(state.session.playhead+1/p().canvas.fps));
 bind('#split','click',()=>command('split_clip',{time:state.session.playhead}));bind('#delete','click',()=>command('delete_clip'));
 bind('#timelineTab','click',()=>{view='timeline';renderTimeline();});bind('#storyboardTab','click',()=>{view='storyboard';renderTimeline();});
 bind('#timelineZoom','input',e=>{zoom=Number(e.target.value);renderTimeline();});bind('#zoomIn','click',()=>{zoom=Math.min(4,zoom+.25);$('#timelineZoom').value=zoom;renderTimeline();});bind('#zoomOut','click',()=>{zoom=Math.max(1,zoom-.25);$('#timelineZoom').value=zoom;renderTimeline();});
 bind('#fileInput','change',e=>upload([...e.target.files]));
 bind('#libraryContent','input',e=>{if(e.target.id==='librarySearch'){libraryQuery=e.target.value;renderBuiltinResults();}});
 bind('#libraryContent','change',e=>{if(e.target.id==='libraryCollection'){libraryCollection=e.target.value;renderBuiltinResults();}if(e.target.id==='backgroundAnimated')return command('set_background',{background_id:p().canvas.backgroundPreset,animated:e.target.checked});});
 bind('#libraryContent','click',async e=>{
   const b=e.target.closest('button');if(!b)return;
   if(b.hasAttribute('data-import'))$('#fileInput').click();
   if(b.dataset.asset)await addAsset(b.dataset.asset);
   if(b.dataset.text){const s=await command('add_text',{text:b.dataset.text,start:state.session.playhead,duration:Math.min(3,p().duration-state.session.playhead),style:{fontSize:p().canvas.width*Number(b.dataset.size),fontWeight:Number(b.dataset.weight)}});if(s)await choose(s.project.elements.at(-1).id);}
   if(b.dataset.favorite){const id=b.dataset.favorite;favoriteAssets.has(id)?favoriteAssets.delete(id):favoriteAssets.add(id);localStorage.setItem('framecore-favorites',JSON.stringify([...favoriteAssets]));renderBuiltinResults();$(`[data-favorite="${id}"]`)?.focus({preventScroll:true});return;}
   if(b.dataset.libraryKind){libraryKind=b.dataset.libraryKind;renderLibrary();}
   if(b.dataset.builtin){const result=await command('add_library_asset',{asset_id:b.dataset.builtin,start:state.session.playhead,duration:Math.min(3,p().duration-state.session.playhead),width:p().canvas.width*.3,height:p().canvas.height*.3});if(result)await choose(result.project.elements.at(-1).id);}
   if(b.dataset.background)await command('set_background',{background_id:b.dataset.background});
   if(b.dataset.font){const e=selected();if(e&&['text','caption'].includes(e.type))await command('set_property',{property:'style.fontFamily',value:b.dataset.font});else {await command('set_brand',{brand:{font:b.dataset.font},restyle:false});toast('Krój pisma ustawiony dla nowych tekstów.');}}
   if(b.dataset.icon){const result=await command('add_icon',{icon_id:b.dataset.icon,start:state.session.playhead,duration:Math.min(3,p().duration-state.session.playhead)});if(result)await choose(result.project.elements.at(-1).id);}
   if(b.dataset.shape){const circle=b.dataset.shape==='Circle',line=b.dataset.shape==='Line';const s=await command('add_shape',{start:state.session.playhead,duration:Math.min(3,p().duration-state.session.playhead),width:circle?300:600,height:circle?300:line?4:300,style:{background:p().brand.colors.accent,radius:circle?300:16}});if(s)await choose(s.project.elements.at(-1).id);}
   if(b.dataset.motion){if(!selected())return toast('Zaznacz element, aby dodać animację.');await command('apply_motion',{motion_id:b.dataset.motion,duration:.8});await previewSelectedMotion();toast('Animacja zastosowana — podgląd wejścia.');}
   if(b.hasAttribute('data-caption')){const s=await command('add_caption',{text:$('#captionText')?.value||'Twój napis',start:state.session.playhead,duration:Math.min(2,p().duration-state.session.playhead),y:p().canvas.height*.85,height:p().canvas.height*.07,style:{fontSize:p().canvas.width*.035,align:'center'}});if(s)await choose(s.project.elements.at(-1).id);}
   if(b.hasAttribute('data-use-studio-logo'))await useStudioLogo();
   if(b.hasAttribute('data-save-brand')){const colors={};$$('[data-brand-color]').forEach(x=>colors[x.dataset.brandColor]=x.value);await command('set_brand',{brand:{name:$('#brandName').value,font:$('#brandFont').value,colors,logoAssetId:$('#brandLogo').value||null}});toast('Marka zastosowana do projektu.');}
   if(b.hasAttribute('data-plan')||b.dataset.workflow)await planModal(b.dataset.template||'product');
   if(b.hasAttribute('data-connect'))connectModal();if(b.hasAttribute('data-provider')){const data=await call('get_providers');toast(data.providers.length?'Dostawcy dostępni':'Brak dostawcy materiałów AI. Dodaj integrację z własnym kluczem.');}
 });
 bind('#inspectorContent','change',async e=>{const key=e.target.dataset.property;if(!key){if(e.target.dataset.audio){await command('set_audio',{audio:{[e.target.dataset.audio]:Number(e.target.value)}});}if(e.target.hasAttribute('data-project-duration'))await command('set_duration',{duration:Number(e.target.value)});return;}let value=e.target.value;if(e.target.type==='number'||key==='style.fontWeight')value=Number(value);if(key==='motion-duration')await command('apply_motion',{motion_id:selected().motion.id,duration:value});else await command('set_property',{element_id:selected()?.id,property:key,value});});
 bind('#inspectorContent','click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.align)await alignSelected(b.dataset.align);if(b.hasAttribute('data-remove'))await command('delete_clip');if(b.hasAttribute('data-motion-tab'))setTab('Motion');if(b.hasAttribute('data-connect'))connectModal();if(b.hasAttribute('data-inspect')){const report=await call('inspect_project');openModal(modalHeader('KONTROLA PROJEKTU','Sprawdzenie montażu','Kontrola techniczna pomaga wybrać miejsca do obejrzenia.')+`<div class="modal-body">${report.issues.length?report.issues.map(i=>`<p>${esc(i.message)} · ${esc(i.element_id)}</p>`).join(''):'<p>Nie znaleziono problemów w obsługiwanych kontrolach.</p>'}<p class="inspector-note">${esc(report.limitations)}</p></div>`);}
   if(b.hasAttribute('data-capture')){toast('Przygotowanie klatki…');const result=await call('capture_frame',{time:state.session.playhead});openModal(modalHeader('RZECZYWISTA KLATKA',`Klatka ${seconds(result.time)}`,`Rewizja ${result.revision}`)+`<div class="modal-body"><img style="display:block;max-width:100%;max-height:65vh;margin:auto" alt="Klatka filmu" src="data:image/png;base64,${result.data}"></div>`);}
   if(b.hasAttribute('data-duplicate')){const e=selected();const result=await command('duplicate_clip',{element_id:e.id,start:Math.min(p().duration-e.duration,e.start+e.duration)});if(result)await choose(result.project.elements.at(-1).id);}
   if(b.hasAttribute('data-keyframes'))keyframeModal();
   if(b.id==='proposeEdit')await proposeEdit();if(b.dataset.suggestion)$('#agentPrompt').value=b.dataset.suggestion;if(b.dataset.apply)await command('apply_proposal',{proposal_id:b.dataset.apply});if(b.dataset.dismiss)await command('cancel_proposal',{proposal_id:b.dataset.dismiss});});
 bind('#modalContent','input',e=>{if(e.target.id==='briefPrompt'){const m=e.target.value.match(/(\d+)\s*[- ]?(?:second|sekund|s\b)/i);if(m&&Number(m[1])>=3&&Number(m[1])<=600)$('#newDuration').value=m[1];}});
 bind('#modalContent','click',async e=>{
   const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))closeModal();
   if(b.dataset.workflow){$$('.workflow-card').forEach(x=>x.classList.toggle('active',x===b));}
   if(b.id==='saveKeyframes'){const e=selected(),prop=$('#keyframeProperty').value;const points=e.keyframes.filter(k=>k.property!==prop);points.push({property:prop,time:0,value:Number($('#keyframeFrom').value)},{property:prop,time:e.duration,value:Number($('#keyframeTo').value)});await command('set_keyframes',{keyframes:points});closeModal();}
   if(b.id==='clearKeyframes'){await command('set_keyframes',{keyframes:[]});closeModal();}
   if(b.id==='createProject'){const duration=Number($('#newDuration').value);state=await request('/api/create',{name:$('#newName').value,format:$('#newFormat').value,duration,brief:$('#briefPrompt').value,workflow:$('.workflow-card.active')?.dataset.workflow||'Premiera produktu'});localStorage.setItem('framecore-project',p().id);update();closeModal();toast('Projekt utworzony. Dodaj materiały i przygotuj plan scen.');}
   if(b.id==='assemble'){plan.forEach((s,i)=>s.message=$(`[data-plan-message="${i}"]`).value);if(p().elements.length){closeModal();await command('propose_changes',{description:'Zastąp montaż sprawdzonym planem scen',commands:[{name:'assemble_storyboard',args:{scenes:plan,replace:true,template_id:planTemplateId}}]});inspectorTab='agent';renderInspector();}else{await command('assemble_storyboard',{scenes:plan,template_id:planTemplateId});closeModal();const title=p().elements.find(x=>x.type==='text');if(title)await choose(title.id);await seek(.8);}toast('Edytowalny montaż gotowy.');}
   if(b.dataset.format){await command('set_format',{format:b.dataset.format});closeModal();}
   if(b.id==='startExport'){b.disabled=true;const job=await request('/api/export',{project_id:p().id,expected_revision:p().revision});$('#exportStatus').innerHTML='<div class="export-progress"><span style="width:5%"></span></div><p class="panel-subtitle">Renderowanie filmu…</p>';renderPoll=setInterval(async()=>{try{const j=await request('/api/job/'+job.id);$('#exportStatus').innerHTML=`<div class="export-progress"><span style="width:${j.progress*100}%"></span></div><p class="panel-subtitle">${j.status==='complete'?'Gotowe. '+j.width+' × '+j.height+' · '+j.duration.toFixed(1)+' sekund':j.status==='failed'?esc(j.error):'Renderowanie rewizji '+j.revision+'…'}</p>${j.status==='complete'?`<a class="primary-button" style="text-decoration:none" href="${j.url}" download>Pobierz MP4 ${icon('download-simple')}</a>`:''}`;if(['complete','failed'].includes(j.status))clearInterval(renderPoll);}catch(err){clearInterval(renderPoll);toast(err.message);}},1000);}
   if(b.dataset.project){state=await request('/api/project/'+b.dataset.project);localStorage.setItem('framecore-project',p().id);previewRevision=-1;update();closeModal();}
 });
 bind('#projectMenu','click',async()=>{const result=await request('/api/projects');openModal(modalHeader('TWOJE LOKALNE STUDIO','Twoje projekty','Projekty są zapisane na tym komputerze. Wybierz projekt do dalszej pracy.')+`<div class="modal-body">${result.projects.map(x=>`<button class="list-button" data-project="${x.id}">${icon('film-strip')}<span><strong>${esc(x.name)}</strong><small>Rewizja ${x.revision} · ${new Date(x.updatedAt).toLocaleDateString()}</small></span></button>`).join('')}</div>`);});
 bind('#shortcuts','click',()=>openModal(modalHeader('PRACUJ SPRAWNIEJ','Skróty klawiaturowe','Skróty działają poza polami tekstowymi.')+'<div class="modal-body"><div class="panel-subtitle">Spacja — odtwarzaj / pauza<br>← / → — poprzednia / następna klatka<br>S — podziel przy wskaźniku<br>Delete — usuń zaznaczony klip<br>Ctrl / ⌘ Z — cofnij<br>Ctrl / ⌘ Shift Z — ponów</div></div>'));
 bind('#timelineContent','click',async e=>{if(drag)return;const scene=e.target.closest('[data-scene-time]');if(scene){await seek(Number(scene.dataset.sceneTime));return;}const track=e.target.closest('[data-track]');if(track){const t=p().tracks.find(t=>t.id===track.dataset.track);await command('set_track',{track_id:t.id,property:track.dataset.trackProp,value:!t[track.dataset.trackProp]});return;}const clip=e.target.closest('[data-clip]');if(clip){await choose(clip.dataset.clip);return;}const ruler=e.target.closest('[data-ruler],.track-lane');if(ruler){const r=ruler.getBoundingClientRect();await seek((e.clientX-r.left)/r.width*p().duration);}});
 $('#timelineContent').addEventListener('pointerdown',timelineDrag);$('#canvasOverlay').addEventListener('pointerdown',canvasDrag);
 for(const el of [$('.library'),$('.canvas-area')]){el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drop-active');});el.addEventListener('dragleave',()=>el.classList.remove('drop-active'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drop-active');upload([...e.dataTransfer.files]).catch(err=>toast(err.message));});}
 document.addEventListener('keydown',e=>{if(panelKeydown(e))return;if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('#modal').open)return;if(e.code==='Space'){e.preventDefault();togglePlay();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();command(e.shiftKey?'redo':'undo').catch(()=>{});}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();seek(state.session.playhead+(e.key==='ArrowRight'?1:-1)/p().canvas.fps);}else if(e.key.toLowerCase()==='s'&&selected())command('split_clip',{time:state.session.playhead}).catch(()=>{});else if(['Delete','Backspace'].includes(e.key)&&selected()){e.preventDefault();command('delete_clip').catch(()=>{});}});
 player.addEventListener('ready',()=>{player.seek(state.session.playhead);});player.addEventListener('timeupdate',e=>{if(!playing)return;state.session.playhead=e.detail.currentTime;$('#timeNow').textContent=seconds(state.session.playhead);paintPlayhead();renderOverlay();});player.addEventListener('ended',()=>{stopPlayback();call('set_playhead',{time:state.session.playhead}).catch(()=>{});});player.addEventListener('error',e=>toast('Podgląd: '+(e.detail?.message||'nie udało się wczytać')));
 new ResizeObserver(()=>fitCanvas()).observe($('.canvas-area'));
}
function timelineDrag(event){
 const clip=event.target.closest('[data-clip]');if(!clip||busy)return;event.preventDefault();stopPlayback();const e=p().elements.find(e=>e.id===clip.dataset.clip),lane=clip.parentElement,r=lane.getBoundingClientRect(),x=event.clientX,oldStart=e.start,oldDuration=e.duration;
 const handle=event.target.closest('.trim-handle'),left=handle&&!handle.classList.contains('right');let changed=false,newStart=oldStart,newDuration=oldDuration;
 const move=ev=>{const delta=(ev.clientX-x)/r.width*p().duration;const quantum=$('#snap').checked?.1:1/p().canvas.fps;const d=Math.round(delta/quantum)*quantum;changed=Math.abs(d)>.001;
   if(handle){if(left){newStart=Math.max(0,Math.min(oldStart+oldDuration-.05,oldStart+d));newDuration=oldDuration+oldStart-newStart;}else newDuration=Math.max(.05,Math.min(p().duration-oldStart,oldDuration+d));}
   else newStart=Math.max(0,Math.min(p().duration-oldDuration,oldStart+d));
   clip.style.left=newStart/p().duration*100+'%';clip.style.width=newDuration/p().duration*100+'%';drag=changed;
 };
 const up=async()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);try{if(changed){await command(handle?'trim_clip':'move_clip',{element_id:e.id,start:newStart,...(handle?{duration:newDuration}:{})});}await choose(e.id);}catch(err){toast(err.message);}setTimeout(()=>drag=false,0);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true});
}
function canvasDrag(event){
 const box=event.target.closest('[data-canvas]');if(!box||busy)return;event.preventDefault();stopPlayback();const e=p().elements.find(x=>x.id===box.dataset.canvas),scale=$('#canvasWrap').clientWidth/p().canvas.width,x=event.clientX,y=event.clientY;
 let nx=e.x,ny=e.y,changed=false;
 const move=ev=>{nx=Math.round(e.x+(ev.clientX-x)/scale);ny=Math.round(e.y+(ev.clientY-y)/scale);changed=Math.abs(ev.clientX-x)+Math.abs(ev.clientY-y)>3;box.style.left=nx*scale+'px';box.style.top=ny*scale+'px';};
 const up=async()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);try{if(changed)await command('move_element',{element_id:e.id,x:nx,y:ny});await choose(e.id);}catch(err){toast(err.message);}};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true});
}
async function init(){
 fillIcons();renderRail();setupEvents();motions=(await request('/api/motion')).components;iconLibrary=(await request('/api/command',{name:'list_icons'})).icons;templateLibrary=(await request('/api/command',{name:'list_templates'})).templates;builtinLibrary=(await request('/api/command',{name:'list_library'})).assets;fontLibrary=(await request('/api/command',{name:'list_fonts'})).fonts;backgroundLibrary=(await request('/api/command',{name:'list_backgrounds'})).backgrounds;const list=(await request('/api/projects')).projects;
 const saved=localStorage.getItem('framecore-project');if(list.length){state=await request('/api/project/'+(list.find(x=>x.id===saved)?.id||list[0].id));}else{state=await request('/api/demo',{});}
 localStorage.setItem('framecore-project',p().id);update();
 setInterval(async()=>{if(!p()||busy||pendingSelections||uploading||drag||playing||$('#modal').open||document.activeElement?.matches('input,textarea,select,[contenteditable=true]'))return;try{const version=selectionVersion,projectId=p().id,revision=p().revision;const next=await request('/api/project/'+projectId);if(busy||pendingSelections||version!==selectionVersion||p().id!==projectId||p().revision!==revision)return;if(next.project.revision!==p().revision||JSON.stringify(next.session)!==JSON.stringify(state.session)||JSON.stringify(next.proposals.map(x=>[x.id,x.status]))!==JSON.stringify(state.proposals.map(x=>[x.id,x.status]))){state=next;update();}}catch(err){$('#saveState').textContent='Połącz ponownie ze studiem';}},800);
}
init().catch(e=>{toast(e.message);$('#projectMenu').textContent='Studio niedostępne';console.error(e);});
